"""Decoder for the internal ``trk`` telemetry record format.

The feed consists of length-prefixed frames.  Multi-byte fields in frame
payloads are big-endian, despite the frame length itself being little-endian.
Each frame ends in an XOR checksum of its payload.
"""

from datetime import datetime, timedelta, timezone


_SAMPLE = 0x02
_BATCH = 0x07
_EPOCH = datetime(2000, 1, 2, tzinfo=timezone.utc)
_FLAG_NAMES = (
    (0x01, "low_battery"),
    (0x02, "recal"),
    (0x04, "stale"),
)


def _flags(value: int) -> list[str]:
    """Turn the known flag bits into their public names."""
    return [name for bit, name in _FLAG_NAMES if value & bit]


def _uint(data: bytes) -> int:
    return int.from_bytes(data, "big")


def decode_records(data: bytes) -> list[dict]:
    """Decode all records in a captured ``trk`` byte stream.

    Frames have a one-byte type, a two-byte little-endian payload length,
    payload bytes, and a one-byte checksum.  A malformed/incomplete frame is
    rejected rather than returning a partial decode.
    """
    records: list[dict] = []
    offset = 0

    while offset < len(data):
        if len(data) - offset < 3:
            raise ValueError("truncated record header")

        record_type = data[offset]
        payload_length = int.from_bytes(data[offset + 1 : offset + 3], "little")
        payload_start = offset + 3
        payload_end = payload_start + payload_length
        if payload_end >= len(data):  # one checksum byte must also remain
            raise ValueError("truncated record payload")

        payload = data[payload_start:payload_end]
        checksum = data[payload_end]
        calculated = 0
        for byte in payload:
            calculated ^= byte
        if calculated != checksum:
            raise ValueError("checksum mismatch")

        if record_type == _SAMPLE:
            if payload_length != 8:
                raise ValueError("invalid sample record length")
            minutes = _uint(payload[0:4])
            timestamp = (_EPOCH + timedelta(minutes=minutes)).strftime(
                "%Y-%m-%dT%H:%M:%SZ"
            )
            records.append(
                {
                    "type": "sample",
                    "ts": timestamp,
                    "value": _uint(payload[4:7]) / 1000,
                    "flags": _flags(payload[7]),
                }
            )
        elif record_type == _BATCH:
            if payload_length < 3:
                raise ValueError("invalid batch record length")
            count = _uint(payload[0:2])
            if payload_length != 2 + count * 2 + 1:
                raise ValueError("invalid batch record length")
            records.append(
                {
                    "type": "batch",
                    "values": [
                        _uint(payload[2 + i * 2 : 4 + i * 2]) / 100
                        for i in range(count)
                    ],
                    "flags": _flags(payload[-1]),
                }
            )
        else:
            raise ValueError(f"unknown record type 0x{record_type:02x}")

        offset = payload_end + 1

    return records
